gs.include("ScheduleOnce");

var LOG_SOURCE = "CRITICAL_UPDATE_GLIDEENCRYPTER_FIX";
gs.log("Fix Script execution started!", LOG_SOURCE);

var script = "runFixScript();\n"
+ "function runFixScript() {\n"
    + "var CRITICAL_UPDATE_SYS_ID = \"8eade0d9ffd03110684fffffffffffef\";\n"
    + "var PROCESS_DEFINITION_SYS_ID = \"cf8e24e743907110adf71f062bb8f2ba\";\n"
    + "var LOG_SOURCE = \"CRITICAL_UPDATE_GLIDEENCRYPTER_FIX\";\n"
	+ "gs.log(\"Schedule Job execution started!\", LOG_SOURCE);\n"
    + "var variableGr = new GlideRecord('sys_variable_value');\n"
    + "variableGr.addEncodedQuery('variable.label=Description^document=sys_pd_activity_context^valueCONTAINSDeprecated API: GlideEncrypter^valueCONTAINSDeprecated APIs');\n"
    + "variableGr.query();\n"
    + "var variableUpdated = false;\n"
    + "while (variableGr.next()) {\n"
        + "variableGr.value = \"<ul style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">\\n<li>Navigate to <strong>All</strong> &gt; <strong>Instance Scan</strong> &gt; <strong>Suites</strong>.</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">In the <strong>Suites</strong> list, select <strong>Deprecated APIs</strong></li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">In the <strong>Suites</strong> record, select <strong>GlideEncrypter</strong> from the <strong>Child Suites</strong> related list.\\n<ul style=\\\"list-style-type: circle; font-family: lato; font-size: 16px; font-weight: 400;\\\">\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">In the <strong>Suite</strong> record, select <strong>Execute Suite Scan</strong> to run the scan.\\n<ul style=\\\"list-style-type: circle; font-family: lato; font-size: 16px; font-weight: 400;\\\">\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">During the scan execution a <strong>Execute Suite Scan</strong> window displays the progress of the scan.</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\"><strong>Note:</strong> This scan checks only records that have been created or modified by the customer.  ServiceNow  handled removal of <strong>GlideEncrypter</strong> usages for any records created by ServiceNow.</li>\\n</ul>\\n</ul>\\n</li>\\n\\n</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">When the scan is complete, select <strong>Go to Result</strong> to view the <strong>Scan Result</strong> record.\\n<ul style=\\\"list-style-type: circle; font-family: lato; font-size: 16px; font-weight: 400;\\\">\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">In the <strong>Scan Result</strong> record, the <strong>Scan Findings</strong> list displays a list of records on your instance that are using the <strong>GlideEncrypter<strong> API.</li>\\n</ul>\\n</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">Select the <strong>Count</strong> field on the <strong>Scan Findings</strong> list to navigate to a record.</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">Modify any scripts in the record that uses the <strong>GlideEncrypter</strong> API.\\n<ul style=\\\"list-style-type: circle; font-family: lato; font-size: 16px; font-weight: 400;\\\">\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">For details on alternatives to <strong>GlideEncrypter</strong>, see <a href=\\\"https://support.servicenow.com/kb?id=kb_article_view&sysparm_article=KB1320986\\\" target=\\\"_blank\\\" rel=\\\"nofollow noopener noreferrer\\\">Alternatives to deprecated GlideEncrypter APIs.</a></li>\\n</ul>\\n</li>\\n<li style=\\\"font-family: lato; font-size: 16px; font-weight: 400;\\\">After removing <strong>GlideEncrypter</strong> calls from your scripts, run the scan again to ensure that there are no remaining calls to the API.</li>\\n</ul>\";\n"
        + "variableUpdated = variableGr.update();\n"
    + "}\n"
    + "if (variableUpdated) {\n"
        + "// Update the Status of Critical Update record to Open.\n"
       + " var criticalUpdateGr = new GlideRecord('sn_critical_update');\n"
        + "if (!criticalUpdateGr.isValid()) {\n"
            + "gs.log(\"Table sn_critical_update is not Valid. Schedule Job cannnot update the Status.\", LOG_SOURCE);\n"
            + "return;\n"
        + "}\n"
        + "criticalUpdateGr.get(CRITICAL_UPDATE_SYS_ID);\n"
        + "if (!criticalUpdateGr.isValidRecord()) {\n"
            + "gs.log(\"sn_critical_update record \" + CRITICAL_UPDATE_SYS_ID + \" is not Valid. Schedule Job cannnot update the Status.\", LOG_SOURCE);\n"
            + "return;\n"
        + "}\n"
        + "criticalUpdateGr.up_update_status = \"open\";\n"
        + "criticalUpdateGr.update();\n"
        + "// Update the state of Process Execution\n"
        + "var pdContextGr = new GlideRecord('sys_pd_context');\n"
        + "if (!pdContextGr.isValid()) {\n"
            + "gs.log(\"Table sys_pd_context is not Valid. Schedule Job cannnot update the state of the process execution.\", LOG_SOURCE);\n"
            + "return;\n"
        + "}\n"
        + "pdContextGr.addQuery('input_record', CRITICAL_UPDATE_SYS_ID);\n"
        + "pdContextGr.query();\n"
        + "if (pdContextGr.next()) {\n"
            + "if (!pdContextGr.isValidRecord()) {\n"
                + "gs.log(\"sys_pd_context record with input_record sys_id\" + CRITICAL_UPDATE_SYS_ID + \" is not Valid. Schedule Job cannnot update the state of the process execution.\", LOG_SOURCE);\n"
                + "return;\n"
            + "}\n"
            + "pdContextGr.state = \"IN_PROGRESS\";\n"
            + "pdContextGr.update();\n"
        + "}\n"
        + "// Update the state of Activity Contexts\n"
        + "var activityGr = new GlideRecord('sys_pd_activity');\n"
        + "if (!activityGr.isValid()) {\n"
            + "gs.log(\"Table sys_pd_activity is not Valid. Schedule Job cannnot update the state of the activity context's flow data.\", LOG_SOURCE);\n"
            + "return;\n"
        + "}\n"
        + "activityGr.addQuery('process_definition', PROCESS_DEFINITION_SYS_ID);\n"
        + "activityGr.query();\n"
        + "while (activityGr.next()) {\n"
            + "var activityContextGr = new GlideRecord('sys_pd_activity_context');\n"
            + "activityContextGr.addQuery('activity_id', activityGr.getValue('sys_id'));\n"
            + "activityContextGr.query();\n"
            + "while (activityContextGr.next()) {\n"
                + "var sysFlowDataSysId = activityContextGr.getValue('associated_record');\n"
                + "var flowDataGr = new GlideRecord('sys_flow_data');\n"
                + "if (!flowDataGr.isValid()) {\n"
                    + "gs.log(\"Table sys_flow_data is not Valid. Schedule Job cannnot update the state of the activity context's flow data.\", LOG_SOURCE);\n"
                    + "return;\n"
                + "}\n"
                + "flowDataGr.get(sysFlowDataSysId);\n"
                + "flowDataGr.state = \"IN_PROGRESS\";\n"
                + "flowDataGr.update();\n"
            + "}\n"
        + "}\n"
    + "}\n"
	+ "gs.log(\"Schedule Job execution completed!\", LOG_SOURCE);\n"
+ "}";

var sched = new ScheduleOnce();
sched.script = script;
sched.label = 'Update GlideEncrypterAPI security center';
sched.schedule();
gs.log("Fix Script execution completed!", LOG_SOURCE);
